#include <bits/stdc++.h>
using namespace std;

using ll = long long;

bool isRight(const array<ll, 3>& x, const array<ll, 3>& y) {
    array<ll, 3> d = {
        (x[0] - x[1]) * (x[0] - x[1]) + (y[0] - y[1]) * (y[0] - y[1]),
        (x[0] - x[2]) * (x[0] - x[2]) + (y[0] - y[2]) * (y[0] - y[2]),
        (x[1] - x[2]) * (x[1] - x[2]) + (y[1] - y[2]) * (y[1] - y[2])
    };
    sort(d.begin(), d.end());
    return d[0] > 0 && d[0] + d[1] == d[2];
}

int main() {
    array<ll, 3> x, y;
    for (int i = 0; i < 3; ++i)
        cin >> x[i] >> y[i];

    if (isRight(x, y)) {
        cout << "RIGHT";
        return 0;
    }

    for (int i = 0; i < 3; ++i) {
        for (int delta : {-1, 1}) {
            x[i] += delta;
            if (isRight(x, y)) {
                cout << "ALMOST";
                return 0;
            }
            x[i] -= delta;

            y[i] += delta;
            if (isRight(x, y)) {
                cout << "ALMOST";
                return 0;
            }
            y[i] -= delta;
        }
    }

    cout << "NEITHER";
    return 0;
}

